    UI_IMPORTED_FILES(Res.string.ui_imported_files, "Imported files"),
    UI_THE_ACTION_COULD_NOT_COMPLETE_PLEASE_TRY_AGAIN(Res.string.ui_the_action_could_not_complete_please_try_again, "The action could not complete. Please try again."),
    UI_INTERNET_ARCHIVE_COULD_NOT_COMPLETE_THE_REQUEST_PLEASE_TRY_AGAIN_LATER(Res.string.ui_internet_archive_could_not_complete_the_request_please_try_again_later, "Internet Archive could not complete the request. Please try again later."),
    IMAGE_ALT_FALLBACK(Res.string.image_alt_fallback, "[Image: %1\$s]"),
    IMAGE_NOT_RENDERED(Res.string.image_not_rendered, "[Image not rendered]");
}

@Immutable
internal class LocalizedStrings(private val values: Map<UiText, String> = emptyMap(), val failed: Boolean = false,
    val localeTag: String = "en", private val plurals: Map<UiPlural, List<String>> = emptyMap()) {
    fun withLoadFailure() = LocalizedStrings(values, failed = true, localeTag = localeTag, plurals = plurals)
    operator fun get(key: UiText): String = values[key] ?: key.fallback
    fun format(key: UiText, vararg args: Any): String {
        return substituteArguments(get(key), args.map { value ->
            if (value is Number) number(value) else value.toString()
        })
    }
    fun number(value: Number, fractionalDigits: Int = 0): String =
        if (value is Int || value is Long) value.toString() // Same ungrouped decimal digits in all shipped locales.
        else formatInterfaceNumber(value.toDouble(), localeTag, fractionalDigits)
    fun quantity(key: UiPlural, count: Int): String {
        require(count >= 0)
        val index = if (count == 1) 0 else 1 // en/es/ca cardinal rules, not a claim about future locales.
        return substituteArguments(plurals[key]?.get(index) ?: key.english[index], listOf(number(count)))
    }
    fun selectedCount(count: Int) = quantity(UiPlural.SELECTED, count)
    fun sourceCount(count: Int) = quantity(UiPlural.SOURCES, count)

    fun message(value: String): String = statusKey(value)?.let { status(value) } ?: get(UiText.GENERIC_TRANSLATION_ERROR)
}
internal val LocalAppStrings = staticCompositionLocalOf { LocalizedStrings() }
